<?php
namespace Database\Seeders;use App\Models\Customer\Company;use App\Models\Customer\Contact;use App\Models\Customer\Tag;use App\Models\Ticket\Ticket;use App\Models\Ticket\TicketStatus;use Illuminate\Database\Seeder;
class HelpdeskDemoSeeder extends Seeder{public function run():void{abort_unless(config('promptbot.demo_mode'),403,'DEMO_MODE must be enabled.');$company=Company::firstOrCreate(['name'=>'Acme Demo'],['status'=>'active','industry'=>'Software','website'=>'https://example.test']);$tag=Tag::firstOrCreate(['name'=>'Demo'],['color'=>'#6366f1','status'=>'active']);foreach(range(1,12) as $n){$contact=Contact::firstOrCreate(['email'=>"customer{$n}@example.test"],['display_name'=>"Demo Customer {$n}",'company_id'=>$company->id,'status'=>$n===1?'vip':'active','source'=>'demo']);$contact->tags()->syncWithoutDetaching([$tag->id]);}$status=TicketStatus::where('is_default',true)->first();if($status&&!Ticket::where('source','demo')->exists())foreach(range(1,8) as $n)Ticket::create(['ticket_number'=>'DEMO-'.str_pad((string)$n,6,'0',STR_PAD_LEFT),'subject'=>"Example support request {$n}",'description'=>'This is safe sample data for the commercial demo workspace.','contact_id'=>Contact::where('email',"customer{$n}@example.test")->value('id'),'status_id'=>$status->id,'priority'=>$n<3?'high':'normal','source'=>'demo']);}}
